// === CHARACTER FREQUENCY MAP ===
function buildFreqMap(s) {
  const freq = new Map();
  for (const ch of s) {
    freq.set(ch, (freq.get(ch) || 0) + 1);
  }
  return freq;
}

// === SLIDING WINDOW FOR SUBSTRING ===
// Template: longest substring with at most k distinct characters
function slidingWindow(s, k) {
  const freq = new Map();
  let left = 0, best = 0;

  for (let right = 0; right < s.length; right++) {
    // expand: add s[right] to window
    freq.set(s[right], (freq.get(s[right]) || 0) + 1);

    // shrink from left when constraint violated
    while (freq.size > k) {
      const lc = s[left++];
      freq.set(lc, freq.get(lc) - 1);
      if (freq.get(lc) === 0) freq.delete(lc);
    }

    best = Math.max(best, right - left + 1);
  }
  return best;
}
